","service":"class AirportSystem_AutoGenerated {
  /*Definition: When the airport adds a new Staff member, the admin records their basic information so the person can be identified and contacted, and their Role and reporting line are clear.
   *Precondition: The staff ID is unique and not already assigned to an existing employee.
   *Postcondition: A new Staff is created with Id, Name, Password, Phone, and Role. If a Boss is provided and exists, the Staff is linked to that Boss, so the organizational relationship is established.*/
  createStaff(
    id: number,
    name: string,
    pswd: string,
    phone: string,
    role: number,
    bossid: number,
  ): boolean {
    /*Definition Start*/
    let existingStaff: Staff = l({
      logic: () =>
        getRepository(Staff).find(
          (s: Staff) =>
            l({
              logic: () => s.Id === id,
              description: "s.Id=id",
            }).build().pass,
        ),
      description: "Staff.allInstance()->any(s:Staff|s.Id=id)",
    }).build().pass;
    let boss: Staff = l({
      logic: () =>
        getRepository(Staff).find(
          (s: Staff) =>
            l({
              logic: () => s.Id === bossid,
              description: "s.Id=bossid",
            }).build().pass,
        ),
      description: "Staff.allInstance()->any(s:Staff|s.Id=bossid)",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsUndefined(existingStaff) === true,
        description: "existingStaff.oclIsUndefined()=true",
      })
        .and({
          logic: () => StandardOPs.oclIsUndefined(boss) === true,
          description: "boss.oclIsUndefined()=true",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let newStaff: Staff;
    return l({
      execute: () => (newStaff = new Staff()),
      description: "newStaff.oclIsNew()",
    })
      .and({
        execute: () => getRepository(Staff).push(newStaff),
        description: "Staff.allInstance()->includes(newStaff)",
      })
      .and({
        execute: () => (newStaff.Id = id),
        description: "newStaff.Id=id",
      })
      .and({
        execute: () => (newStaff.Name = name),
        description: "newStaff.Name=name",
      })
      .and({
        execute: () => (newStaff.Password = pswd),
        description: "newStaff.Password=pswd",
      })
      .and({
        execute: () => (newStaff.Phone = phone),
        description: "newStaff.Phone=phone",
      })
      .and({
        execute: () => (newStaff.Role = role),
        description: "newStaff.Role=role",
      })
      .if({
        logic: () =>
          l({
            logic: () => bossid !== 0,
            description: "bossid<>0",
          }),
        description: "bossid<>0",
        then: l({
          execute: () => (newStaff.Boss = boss),
          description: "newStaff.Boss=boss",
        }),
        else: l({
          logic: () => true,
          description: "true",
        }),
      })
      .and({
        execute: () => true,
        description: "result=true",
      })
      .build().value;
    /*Postcondition End*/
  }
}
