      description: "history.oclIsNew()",
    })
      .and({
        execute: () => (history.StaffId = sid),
        description: "history.StaffId=sid",
      })
      .and({
        execute: () => (history.Reject = reject),
        description: "history.Reject=reject",
      })
      .and({
        execute: () => (history.Suggestion = suggestion),
        description: "history.Suggestion=suggestion",
      })
      .and({
        execute: () => repair.History.push(history),
        description: "repair.History->includes(history)",
      })
      .if({
        logic: () =>
          l({
            logic: () => reject === false,
            description: "reject=false",
          }),
        description: "reject=false",
        then: l({
          execute: () => (repair.Process = repair.Process + 1),
          description: "repair.Process=repair.Process+1",
        }),
        else: l({
          execute: () => (repair.Process = 1),
          description: "repair.Process=-1",
        }),
      })
      .and({
        execute: () => history,
        description: "result=history",
      })
      .build().value;
    /*Postcondition End*/
  }
}
